def AP_Cutoff_Test():
    # Define the necessary variables
    invoice_dates = []
    receipt_dates = []
    period_end_accruals = []
    exceptions = []

    # Collect data for the test
    for invoice in get_invoices():
        invoice_dates.append(invoice.date)
        receipt_dates.append(invoice.receipt_date)

    for accrual in get_accruals():
        period_end_accruals.append(accrual.date)

    for exception in get_exceptions():
        exceptions.append(exception.details)

    # Perform the test
    for invoice in invoice_dates:
        if invoice > get_cutoff_date() and receipt_dates[invoice_dates.index(invoice)] < get_cutoff_date():
            print(f"Invoice {invoice} is outside the cutoff date and has not been received.")

    for accrual in period_end_accruals:
        if accrual > get_cutoff_date():
            print(f"Period-end accrual {accrual} is outside the cutoff date.")

    if exceptions:
        print("The following exceptions were found:")
        for exception in exceptions:
            print(exception)

# Run the AP Cutoff Test
AP_Cutoff_Test()
